      "name": "Price Spread (Max − Min)",
      "description": "The difference between the highest and lowest reported price for each fuel type, measuring market-wide price disparity."
    },
    {
      "name": "Interquartile Range (IQR)",
      "description": "The range between the 25th and 75th percentile prices per fuel type, indicating the typical price band most consumers encounter."
    },
    {
      "name": "Median Update Lag (hours)",
