from html.parser import HTMLParser
class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tags = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in ('br','hr','img','input','meta','link'):
            self.tags.append(tag)
    def handle_endtag(self, tag):
        if self.tags and self.tags[-1] == tag:
            self.tags.pop()
        elif tag in self.tags:
            self.errors.append(f'Mismatched closing tag: {tag}')

v = Validator()
with open('/app/output/final_report.html') as f:
    v.feed(f.read())
if v.errors:
    print('Errors:', v.errors[:5])
else:
    print('HTML structure looks valid')
print('Unclosed tags:', [t for t in v.tags if t not in ('svg','defs','path','g','text','line','rect','polygon','polyline','circle','clippath','use','style','desc','title')][:10])
"

